"""Registration/publication metadata contracts, independent of file I/O."""
import hashlib
import json
import re
from pathlib import PurePosixPath

PUBLICATION_SCHEMA = 'pcb-ingestion-publication-v2'


def require(condition, reason):
    if not condition:
        raise ValueError(reason)


def digest_registry(config):
    return hashlib.sha256(json.dumps(config, sort_keys=True).encode()).hexdigest()


def validate_registry(config):
    require(isinstance(config, dict), 'Registry must be an object')
    require(config.get('schema') == 'pcb-ingestion-registration-v1', 'Unsupported registry schema')
    datasets = config.get('datasets')
    require(isinstance(datasets, list), 'Dataset registration must be a list')
    require(all(isinstance(d, dict) for d in datasets), 'Dataset must be an object')
    ids = [d.get('id') for d in datasets]
    require(all(isinstance(i, str) and i for i in ids) and len(ids) == len(set(ids)), 'Invalid/duplicate dataset IDs')
    for dataset in datasets:
        for key in ('sources', 'evidence'):
            rows = dataset.get(key)
            require(isinstance(rows, list) and rows, 'Missing dataset ' + key)
            for row in rows:
                require(isinstance(row, dict), 'Binding must be an object')
                require(isinstance(row.get('path'), str) and bool(row['path']), 'Invalid binding path')
                require(isinstance(row.get('sha256'), str) and re.fullmatch('[0-9a-f]{64}', row['sha256']), 'Invalid binding hash')


def generation_review():
    """A build cannot inherit a review of a different source/run snapshot."""
    return {
        'status': 'NOT_RUN',
        'reason': 'NO_REVIEW_ATTACHED_TO_THIS_PUBLICATION',
        'scope': 'AT_GENERATION',
    }


def intake_projection(config, read_bytes):
    """Describe retained intake metadata, bound through the registered external seal.

    read_bytes accepts checkout-relative paths. No source files are rewritten.
    Synthetic publisher fixtures without a sealed intake have no projection.
    """
    seal = config['dataset_seal']
    seal_path = PurePosixPath(seal['path'])
    if seal_path.name != 'SHA256SUMS':
        return None
    package = str(seal_path.parent)
    raw = read_bytes(seal['path'])
    require(hashlib.sha256(raw).hexdigest() == seal['sha256'], 'Intake seal mismatch')
    checksums = {}
    for line in raw.decode().splitlines():
        digest, separator, path = line.partition('  ')
        require(separator and re.fullmatch('[0-9a-f]{64}', digest) and path not in checksums,
                'Invalid intake checksum entry')
        checksums[path] = digest
    artifacts = {}
    manifest = None
    for name, relative in [('entry', 'index.md'), ('manifest', 'metadata/manifest.json'),
                           ('checksums', 'SHA256SUMS')]:
        path = str(seal_path.parent / relative)
        digest = seal['sha256'] if name == 'checksums' else checksums.get(relative)
        data = read_bytes(path)
        require(digest and hashlib.sha256(data).hexdigest() == digest,
                'Intake metadata does not match seal: ' + relative)
        artifacts[name] = {'path': path, 'sha256': digest, 'snapshot': 'intake/' + relative}
        if name == 'manifest':
            manifest = json.loads(data)
    dataset = next((d for d in config['datasets'] if d['id'] == manifest['dataset_id']), None)
    if dataset is None:
        return None
    registered = {(r['path'], r['sha256']) for r in dataset['sources']}
    files = [row for row in manifest['files'] if row['path'].startswith('raw/')]
    require(files, 'Missing intake raw file records')
    for row in files:
        path = str(seal_path.parent / row['path'])
        require((path, row['sha256']) in registered and checksums.get(row['path']) == row['sha256'],
                'Intake raw file is not registered/sealed: ' + path)
    return {'dataset_id': dataset['id'], 'package_root': package,
            'artifacts': artifacts, 'input_sets': manifest['input_sets'], 'raw_files': files}


def verify_generation_review(receipt, ingestion):
    review = receipt.get('cursor_review')
    if isinstance(review, dict):
        require(review == generation_review(), 'Invalid generation-time review status')
        require(ingestion.get('cursor_review') == review, 'Scene/receipt review status mismatch')
    else:
        require(review == 'NOT_RUN: CHANNEL_UNAVAILABLE', 'Missing/invalid legacy generation review')
        require('cursor_review' not in ingestion, 'Structured scene review requires a structured receipt review')
    # Earlier v2 publications retain their frozen string metadata. An external
    # review addendum remains separate from generation-time publication evidence.

"""Build, reopen or export the bounded R140 common catalogue locally."""
import argparse
import json
import os
from pathlib import Path
import subprocess
import sys

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from src.common_catalogue import publish,retrieve,export_context,verify_bundle,validate_positive,SCHEMA
from src.ingestion_files import write_json,local


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action',choices=['build','retrieve','verify','export','acceptance'])
    parser.add_argument('--bundle',type=Path)
    parser.add_argument('--revision')
    parser.add_argument('--output',type=Path,default=ROOT/'out/common_catalogue/materialized')
    parser.add_argument('--fail-before-publish',action='store_true')
    args=parser.parse_args(argv)
    if args.action=='build':
        run,revision=publish(ROOT,args.output,fail_before_publish=args.fail_before_publish)
        result={'schema':SCHEMA,'status':'PASS','run':str(run),'dataset_revision':revision,'writer_pid':os.getpid()}
    elif args.action=='acceptance':
        require_output=args.output.resolve()
        if not require_output.is_relative_to(ROOT/'out') or require_output.exists():raise ValueError('Acceptance output must be a new checkout/out directory')
        require_output.mkdir(parents=True)
        env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1'}
        def run(action,*arguments):
            command=[sys.executable,str(Path(__file__).resolve()),action,*map(str,arguments)]
            child=subprocess.run(command,cwd=ROOT,env=env,capture_output=True,text=True)
            (require_output/(action+'.stdout.json')).write_text(child.stdout)
            (require_output/(action+'.stderr.log')).write_text(child.stderr)
            if child.returncode:raise ValueError(action+' failed: '+child.stdout[-1000:]+child.stderr[-1000:])
            return json.loads(child.stdout)
        built=run('build','--output',require_output/'catalogue')
        bundle=built['run'];revision=built['dataset_revision']
        reopened=run('retrieve','--bundle',bundle,'--revision',revision);validate_positive(reopened)
        write_json(require_output/'reopened.json',reopened)
        exported=run('export','--bundle',bundle,'--revision',revision,'--output',require_output/'selection')
        offline=run('retrieve','--bundle',exported['destination'],'--revision',revision)
        write_json(require_output/'export_reopened.json',offline)
        if not (built['writer_pid']!=reopened['reader_pid']!=offline['reader_pid'] and reopened['result_sha256']==offline['result_sha256']):raise ValueError('Fresh-process/export identity failed')
        result={'schema':SCHEMA,'status':'PASS','scope':'Bounded R140 persistence/reopen/correspondence/diagnostic export',
                'run':bundle,'dataset_revision':revision,'result_sha256':reopened['result_sha256'],
                'writer_pid':built['writer_pid'],'reader_pid':reopened['reader_pid'],'export_reader_pid':offline['reader_pid'],
                'output':str(require_output),'independent_review':'NOT_RUN','engineering_acceptance':'NOT_ESTABLISHED'}
        write_json(require_output/'acceptance.json',result)
    else:
        if not args.bundle or not args.revision:parser.error('--bundle and explicit --revision are required')
        bundle=local(ROOT,str(args.bundle))
        if args.action=='verify':
            envelope=verify_bundle(bundle,args.revision);result={'schema':SCHEMA,'status':'PASS','dataset_revision':args.revision,'artifacts':len(envelope['artifacts'])}
        elif args.action=='retrieve':result=retrieve(bundle,args.revision)
        else:
            output=local(ROOT,str(args.output))
            if not output.is_relative_to(ROOT/'out'):raise ValueError('Export stays under out/')
            result=export_context(bundle,output,args.revision)
    print(json.dumps(result,allow_nan=False));return 0


if __name__=='__main__':
    try:sys.exit(main())
    except Exception as error:
        print(json.dumps({'status':'FAIL','error':str(error)}));sys.exit(1)

